import math
import json

def rad(deg):
    return math.radians(deg)

def lhs(x):
    # Original expression: 4 sin x sin(60 - x) sin(60 + x), x in degrees
    return 4 * math.sin(rad(x)) * math.sin(rad(60 - x)) * math.sin(rad(60 + x))

# Candidate simplified forms (x in degrees)
candidates = {
    "sin(3x)": lambda x: math.sin(rad(3 * x)),
    "-sin(3x)": lambda x: -math.sin(rad(3 * x)),
    "cos(3x)": lambda x: math.cos(rad(3 * x)),
    "-cos(3x)": lambda x: -math.cos(rad(3 * x)),
    "sin(x)": lambda x: math.sin(rad(x)),
    "cos(x)": lambda x: math.cos(rad(x)),
    "sin(2x)": lambda x: math.sin(rad(2 * x)),
    "cos(2x)": lambda x: math.cos(rad(2 * x)),
}

# Exhaustive grid of sample points, avoiding nothing: identity should hold everywhere
samples = [k * 3.7 for k in range(-60, 61)]  # -222 to 222 degrees
tol = 1e-9

results = {}
for name, f in candidates.items():
    max_err = max(abs(lhs(x) - f(x)) for x in samples)
    results[name] = max_err

matches = [name for name, err in results.items() if err < tol]

if len(matches) == 1:
    final_answer = matches[0]
    evidence = {
        "samples_checked": len(samples),
        "tolerance": tol,
        "matched_candidates": matches,
        "max_abs_error": results[matches[0]],
    }
    output = {"final_answer": final_answer, "evidence": evidence}
else:
    output = {
        "final_answer": "UNSUPPORTED",
        "evidence": {
            "samples_checked": len(samples),
            "tolerance": tol,
            "matched_candidates": matches,
        },
    }

print(json.dumps(output))
